delete  FROM compta_compte WHERE typecompte=3 ;
UPDATE compta_compte SET TYPECOMPTE ='TYPC000005' WHERE typecompte='2';

DELETE FROM compta_compte c
WHERE c.id LIKE 'COCSOC%'
  AND c.typecompte = '1'
  AND NOT EXISTS (
      SELECT 1
      FROM as_ingredients i
      WHERE i.compte_achat = c.compte
  )
  AND NOT EXISTS (
      SELECT 1
      FROM compta_sous_ecriture s
      WHERE s.compte = c.compte
  );

